/**
 * Scaffold a Slack channel into an agent-serve project.
 *
 * `initSlackChannel` is the create-safe channel writer.
 * only. DIY manifests + Slack CLI `.slack/` live in
 * {@link initSlackManual} so `slack create` cannot reach them.
 */
import { mkdir, writeFile } from "node:fs/promises";
import { basename, join, resolve } from "node:path";
import { CLI_COMMAND_NAME as CLI, PACKAGE_NAME } from "../../internal/distribution.js";
import { projectPath, resolveProjectRoot } from "../../internal/project-layout.js";
import { writeSlackCliProject } from "./cli-project.js";
import { envPrefixFromName, slackEnvKeys } from "./credentials.js";
import { buildSlackManifestPair, slackManifestFileEntries } from "./manifest.js";
import { initialSlackSetupStatus } from "./setup.js";
function resolveSlackInitTarget(options) {
    const rootDir = resolve(options.dir);
    const envPrefix = options.envPrefix === ""
        ? undefined
        : (options.envPrefix ?? envPrefixFromName(basename(rootDir)));
    return {
        rootDir,
        name: options.name ?? basename(rootDir),
        envPrefix,
        envKeys: slackEnvKeys(envPrefix),
    };
}
async function writeExclusive(rootDir, rel, contents) {
    const abs = join(rootDir, rel);
    await mkdir(join(abs, ".."), { recursive: true });
    await writeFile(abs, contents, { flag: "wx" });
}
function slackChannelSource(target, kind) {
    const envPrefixLine = target.envPrefix === undefined ? "" : `  envPrefix: ${JSON.stringify(target.envPrefix)},\n`;
    const tokenLines = kind === "manual"
        ? ` * Tokens: ${target.envKeys.bot} + ${target.envKeys.app}\n * (see .agent-serve/slack/env.example).`
        : ` * Tokens: ${target.envKeys.bot} + ${target.envKeys.app}`;
    const setupLine = kind === "manual"
        ? ` * Full setup: ${CLI} slack setup`
        : ` * Full setup: ${CLI} slack create --dir .`;
    return `import { slackChannel } from "${PACKAGE_NAME}/channels/slack";

/**
 * Slack channel (Socket Mode).
 *
${tokenLines}
 *
${setupLine}
 */
export default slackChannel({
${envPrefixLine}  // Streaming and thinking steps default to true.
  suggestedPrompts: [
    { title: "Help", message: "How can you help me?" },
    { title: "Status", message: "What are you working on?" },
  ],
});
`;
}
/** Create-safe: write only the authored Slack channel. */
export async function initSlackChannel(options) {
    const target = resolveSlackInitTarget(options);
    const channelPath = projectPath(resolveProjectRoot(target.rootDir), "channels/slack.ts");
    await writeExclusive(target.rootDir, channelPath, slackChannelSource(target, "create"));
    return {
        rootDir: target.rootDir,
        files: [channelPath],
        envPrefix: target.envPrefix,
        envKeys: target.envKeys,
    };
}
/**
 * `slack init --manual`: channel file plus DIY manifests
 * (`managedByCursor: false`), Slack CLI `.slack/` project, env.example,
 * and setup-status.json.
 */
export async function initSlackManual(options) {
    const target = resolveSlackInitTarget(options);
    const channelPath = projectPath(resolveProjectRoot(target.rootDir), "channels/slack.ts");
    const files = [];
    const write = async (rel, contents) => {
        if (options.dryRun !== true) {
            await writeExclusive(target.rootDir, rel, contents);
        }
        files.push(rel);
    };
    await write(channelPath, slackChannelSource(target, "manual"));
    const pair = buildSlackManifestPair({
        name: target.name,
        managedByCursor: false,
        description: options.description,
    });
    await write(".agent-serve/slack/env.example", `# Copy to .env.local (or export in your shell). Use the *dev* Slack app
# for local development; use the Prod app tokens in deployment secrets.
#
# Multi-agent serve needs a distinct Slack app (and token pair) per agent.

${target.envKeys.bot}=xoxb-...
${target.envKeys.app}=xapp-...
`);
    await write(".agent-serve/slack/setup-status.json", `${JSON.stringify(initialSlackSetupStatus({
        envPrefix: target.envPrefix,
        envKeys: target.envKeys,
    }), null, 2)}\n`);
    const manifests = slackManifestFileEntries(pair);
    if (options.dryRun === true) {
        files.push(".slack/get-manifest.mjs", ...manifests.map((file) => `.slack/${file.name}`), ".slack/hooks.json");
    }
    else {
        files.push(...(await writeSlackCliProject(target.rootDir, manifests)));
    }
    return {
        rootDir: target.rootDir,
        files,
        envPrefix: target.envPrefix,
        envKeys: target.envKeys,
    };
}
